import pytest

import factory


@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
def test_faker_decider_defaults(chance, expected):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'boolean', locale='en_US',
                chance_of_getting_true=factory.LazyFunction(lambda: chance),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory.create_batch(3) == [{'value': expected}] * 3


def test_nested_maybe_decider():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory() == {'value': 'yes'}


def test_overrides_apply_to_target_not_decider():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker('boolean', chance_of_getting_true=100),
            yes_declaration=factory.Faker('boolean', chance_of_getting_true=100),
            no_declaration='no',
        )

    assert ExampleFactory(value__chance_of_getting_true=0) == {'value': False}
